'use strict';

// Match only DM notifications generated by the Borg management website.
// Deliberately do not treat every bot-authored DM as a website notification.
const WEBSITE_NOTIFICATION_FOOTERS = new Set([
  'إدارة البرج • مراجعة التسليمات',
  'إدارة البرج • طلبات الإجازة',
  'إدارة البرج • الطلبات الإدارية',
  'إدارة البرج • إعادة المهمات',
  'إدارة البرج • تذكير مواعيد التسليم',
]);

const LEGACY_WEBSITE_NOTIFICATION_TITLES = new Set([
  '✅ تم قبول تسليم المهمة',
  '❌ تم رفض تسليم المهمة',
]);

const STAFF_CHAT_NOTIFICATION_MARKER = 'رسالة جديدة في شات الاستاف بالموقع';

// Only the DM sent when someone writes in the website's staff chat room.
function isStaffChatNotificationMessage(message) {
  return String(message?.content || '').includes(STAFF_CHAT_NOTIFICATION_MARKER);
}

function isWebsiteNotificationMessage(message) {
  if (isStaffChatNotificationMessage(message)) return true;

  const embeds = Array.isArray(message?.embeds) ? message.embeds : [];
  for (const item of embeds) {
    // Supports both plain Discord REST payloads and discord.js Embed instances.
    const data = item?.data || item || {};
    const title = String(item?.title || data?.title || '');
    const footer = String(item?.footer?.text || data?.footer?.text || '');
    if (WEBSITE_NOTIFICATION_FOOTERS.has(footer)) return true;
    // The worker's previous task-review DM had no footer. Match its exact old titles
    // so historical site notifications can still be removed without deleting other DMs.
    if (LEGACY_WEBSITE_NOTIFICATION_TITLES.has(title)) return true;
  }
  return false;
}

// Final reply text for the clear-notifications commands (all website alerts vs. staff chat alerts only).
function formatClearNotificationsSummary(stats, staffChatOnly = false) {
  const common = [
    `المستخدمون المحتمل وصول تنبيهات إليهم: **${stats.recipients}**`,
    `محادثات الخاص التي تم فحصها: **${stats.channelsScanned}**`,
  ];
  if (staffChatOnly) {
    return [
      '✅ انتهى حذف تنبيهات شات الاستاف من الخاص.',
      ...common,
      `تنبيهات شات الاستاف المحذوفة: **${stats.messagesDeleted}**`,
      `أخطاء حذف التنبيهات: **${stats.messageErrors}**`,
      `محادثات تعذر الوصول إليها: **${stats.recipientErrors}**`,
      'تم تجاهل باقي تنبيهات الموقع (التسليمات والإجازات والطلبات والتذكيرات) وباقي رسائل البوت ولم يتم حذفها.',
    ].join('\n');
  }
  return [
    '✅ انتهى حذف تنبيهات الموقع من الخاص.',
    ...common,
    `تنبيهات الموقع المحذوفة: **${stats.messagesDeleted}**`,
    `أخطاء حذف التنبيهات: **${stats.messageErrors}**`,
    `محادثات تعذر الوصول إليها: **${stats.recipientErrors}**`,
    'تم تجاهل رسائل البوت الأخرى ولم يتم حذفها.',
  ].join('\n');
}

module.exports = { isWebsiteNotificationMessage, isStaffChatNotificationMessage, formatClearNotificationsSummary };
